import{_ as n,a0 as o,w as d,s as r,I as a,x as e,a1 as t,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 上使用 ZFS 文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 ZFS 文件系统 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 ZFS 文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 ZFS 文件系统 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux","title":"如何在 Ubuntu 上使用 ZFS 文件系统","tag":"201802","desc":""},"relativePath":"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux.md","filePath":"[post].md"}'),h={name:"201802/20170928 How to Use the ZFS Filesystem on Ubuntu Linux.md"};function u(g,s,k,b,c,f){const i=o("Link");return d(),r("div",null,[s[16]||(s[16]=a("h1",{id:"如何在-ubuntu-上使用-zfs-文件系统",tabindex:"-1"},[e("如何在 Ubuntu 上使用 ZFS 文件系统 "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-上使用-zfs-文件系统","aria-label":"Permalink to “如何在 Ubuntu 上使用 ZFS 文件系统”"},"​")],-1)),s[17]||(s[17]=a("p",null,[a("img",{src:"https://www.maketecheasier.com/assets/uploads/2017/09/zfs-feat.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在 Linux 系统上，有大量的",-1)),t(i,{href:"https://www.maketecheasier.com/best-linux-filesystem-for-ssd/"},{default:l(()=>[...s[0]||(s[0]=[e("文件系统",-1)])]),_:1}),s[2]||(s[2]=e("可以使用，那么我们为什么还要尝试一个新的文件系统？它们都工作的很好，不是吗？但是它们并不完全相同，其中的一些文件系统具有非常突出的优点，例如 ZFS。",-1))]),s[18]||(s[18]=p('<h3 id="为什么选择-zfs" tabindex="-1">为什么选择 ZFS <a class="header-anchor" href="#为什么选择-zfs" aria-label="Permalink to “为什么选择 ZFS”">​</a></h3><p>ZFS 非常的优秀。这是一个真正现代的文件系统，内置的功能对于处理大量的数据很有意义。</p><p>现在，如果您正在考虑将 ZFS 用于您的超高速 NVMe SSD，这可能不是一个最佳选择。 它比别的文件系统要慢，不过，这完全没有问题， 它旨在存储大量的数据并保持安全。</p><p>ZFS 消除了建立传统 RAID 阵列（LCTT 译注：独立磁盘冗余阵列）的需要。 相反，您可以创建 ZFS 池，甚至可以随时将驱动器添加到这些池中。 ZFS 池的行为操作与 RAID 几乎完全相同，但功能内置于文件系统中。</p><p>ZFS 也可以替代 LVM （LCTT 译注：逻辑盘卷管理），使您能够动态地进行分区和管理分区，而无需处理底层的细节，也不必担心相关的风险。</p><p>这也是一个 CoW （LCTT 译注：写时复制）文件系统。 这里不会提及太多的技术性，这意味着 ZFS 可以保护您的数据免受逐渐损坏的影响。 ZFS 会创建文件的校验和，并允许您将这些文件回滚到以前的工作版本。</p><h3 id="安装-zfs" tabindex="-1">安装 ZFS <a class="header-anchor" href="#安装-zfs" aria-label="Permalink to “安装 ZFS”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-install.jpg" alt="Install ZFS on Ubuntu" title="Install ZFS on Ubuntu"></p><p>在 Ubuntu 上安装 ZFS 非常简单，但对于 Ubuntu LTS （LCTT 译注：长时间支持版本）和最新版本来说，这个过程稍有不同。</p><p><strong>Ubuntu 16.04 LTS</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zfs</span></span></code></pre></div><p><strong>Ubuntu 17.04 及以后</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zfsutils</span></span></code></pre></div><p>当你安装好程序后，可以使用 ZFS 提供的工具创建 ZFS 驱动器和分区。</p><h3 id="创建池" tabindex="-1">创建池 <a class="header-anchor" href="#创建池" aria-label="Permalink to “创建池”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-create-pool.jpg" alt="Create ZFS Pool" title="Create ZFS Pool"></p><p>在 ZFS 中，池大致相当于 RAID 。 它们很灵活且易于操作。</p><h4 id="raid0" tabindex="-1">RAID0 <a class="header-anchor" href="#raid0" aria-label="Permalink to “RAID0”">​</a></h4><p>RAID0 只是把你的硬盘集中到一个池子里面，就像一个巨大的驱动器一样。 它可以提高你的驱动器速度，（LCTT 译注：数据条带化后，并行访问，可以提高文件读取速度）但是如果你的驱动器有损坏，你可能会失丢失数据。</p><p>要使用 ZFS 实现 RAID0，只需创建一个普通的池。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool /dev/sdc /dev/sdd</span></span></code></pre></div><h4 id="raid1-镜像" tabindex="-1">RAID1（镜像） <a class="header-anchor" href="#raid1-镜像" aria-label="Permalink to “RAID1（镜像）”">​</a></h4><p>您可以在 ZFS 中使用 <code>mirror</code> 关键字来实现 RAID1 功能。 RAID1 会创建一个一对一的驱动器副本。 这意味着您的数据一直在备份。 它也提高了性能。 当然，你将一半的存储空间用于了复制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool mirror /dev/sdc /dev/sdd</span></span></code></pre></div><h4 id="raid5-raidz1" tabindex="-1">RAID5/RAIDZ1 <a class="header-anchor" href="#raid5-raidz1" aria-label="Permalink to “RAID5/RAIDZ1”">​</a></h4><p>ZFS 将 RAID5 功能实现为 RAIDZ1。 RAID5 要求驱动器至少是 3 个。并允许您通过将备份奇偶校验数据写入驱动器空间的 1/n（n 是驱动器数），留下的是可用的存储空间。 如果一个驱动器发生故障，阵列仍将保持联机状态，但应尽快更换发生故障的驱动器（LCTT 译注：与原文翻译略有不同，原文是驱动器的数目是三的倍数，根据 wiki， RAID5 至少需要 3 块驱动器，也可以从下面的命令中猜测)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool raidz1 /dev/sdc /dev/sdd /dev/sde</span></span></code></pre></div><h4 id="raid6-raidz2" tabindex="-1">RAID6/RAIDZ2 <a class="header-anchor" href="#raid6-raidz2" aria-label="Permalink to “RAID6/RAIDZ2”">​</a></h4><p>RAID6 与 RAID5 几乎完全相同，但它至少需要四个驱动器。 它将奇偶校验数据加倍，最多允许两个驱动器损坏，而不会导致阵列关闭（LCTT 译注：这里也与原文略有出入，原文是驱动器的数目是四的倍数，根据 wiki ，RAID6 至少需要四个驱动器)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool raidz2 /dev/sdc /dev/sdd /dev/sde /dev/sdf</span></span></code></pre></div><h4 id="raid10-条带化镜像" tabindex="-1">RAID10（条带化镜像） <a class="header-anchor" href="#raid10-条带化镜像" aria-label="Permalink to “RAID10（条带化镜像）”">​</a></h4><p>RAID10 旨在通过数据条带化提高存取速度和数据冗余来成为一个两全其美的解决方案。 你至少需要四个驱动器，但只能使用一半的空间。 您可以通过在同一个池中创建两个镜像来创建 RAID10 中的池（LCTT 译注：这里也与原文略有出入，原文是驱动器的数目是四的倍数，根据 wiki， RAID10 至少需要四个驱动器）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool create your-pool mirror /dev/sdc /dev/sdd mirror /dev/sde /dev/sdf</span></span></code></pre></div><h3 id="池的操作" tabindex="-1">池的操作 <a class="header-anchor" href="#池的操作" aria-label="Permalink to “池的操作”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-pool-status.jpg" alt="ZFS pool Status" title="ZFS pool Status"></p><p>还有一些管理工具，一旦你创建了你的池，你就必须使用它们来操作。 首先，检查你的池的状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool status</span></span></code></pre></div><h4 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h4><p>当你更新 ZFS 时，你也需要更新你的池。 当您检查它们的状态时，您的池会通知您任何更新。 要更新池，请运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool upgrade your-pool</span></span></code></pre></div><p>你也可以更新全部池。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool upgrade -a</span></span></code></pre></div><h4 id="添加驱动器" tabindex="-1">添加驱动器 <a class="header-anchor" href="#添加驱动器" aria-label="Permalink to “添加驱动器”">​</a></h4><p>您也可以随时将驱动器添加到池中。 告诉 <code>zpool</code> 池的名称和驱动器的位置，它会处理好一切。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zpool add your-pool /dev/sdx</span></span></code></pre></div><h3 id="其它的一些想法" tabindex="-1">其它的一些想法 <a class="header-anchor" href="#其它的一些想法" aria-label="Permalink to “其它的一些想法”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/zfs-pool-open.jpg" alt="ZFS in File Browser" title="ZFS in File Browser"></p><p>ZFS 会在您的池的根文件系统中创建一个目录。 您可以使用 GUI 文件管理器或 CLI 按名称浏览它们。</p><p>ZFS 非常强大，还有很多其它的东西可以用它来做，但这些都是基础。 这是一个优秀的存储负载文件系统，即使它只是一个用于文件的硬盘驱动器的 RAID 阵列。 ZFS 在 NAS 系统上也非常出色。</p><p>无论 ZFS 的稳定性和可靠性如何，在您的硬盘上实施新的功能时，最好备份您的数据。</p><hr>',51)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),t(i,{href:"https://www.maketecheasier.com/use-zfs-filesystem-ubuntu-linux/"},{default:l(()=>[...s[3]||(s[3]=[e("https://www.maketecheasier.com/use-zfs-filesystem-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=e("作者：",-1)),t(i,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:l(()=>[...s[5]||(s[5]=[e("Nick Congleton",-1)])]),_:1}),s[9]||(s[9]=e(" 译者：",-1)),t(i,{href:"https://github.com/amwps290"},{default:l(()=>[...s[6]||(s[6]=[e("amwps290",-1)])]),_:1}),s[10]||(s[10]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[11]||(s[11]=[e("LCTT",-1)])]),_:1}),s[14]||(s[14]=e(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...s[12]||(s[12]=[e("Linux中国",-1)])]),_:1}),s[15]||(s[15]=e(" 荣誉推出",-1))])])}const F=n(h,[["render",u]]);export{C as __pageData,F as default};
